#!/usr/bin/env node
'use strict';
// F1 synthetic bundle generator. Deterministic: same inputs give byte-identical outputs (fixed timestamps).
// Writes only under local-test-artifacts/f1/ (ignored by Git). Uses Node's zlib for deflate; no packages.
// Usage (repository root): node tests/synthetic/make_bundles.js
// Outputs under local-test-artifacts/f1/:
//   checkpoint/  ZIPs written the way common tools write them (stored, deflate, data descriptors, folders
//                inside, macOS metadata) plus damaged and unsupported archives, and a folder tree; hostile_*.zip:
//                structurally inconsistent archives the reader must refuse or flag.
//   tiers/       the example bundle tiers, each as a ZIP and as a folder: Full (all master columns, the five
//                facility layers, a manifest adding two layers, bundle.json), Partner (master with only the 13
//                required columns, two facility layers, bundle.json naming a renamed file) and Public (13 required
//                columns + Species, no facility layers, no bundle.json). Test scenarios only, not product views.
//   negative/    wrong files, a duplicate master, unclearly named facility layers, a corrupt ZIP, an empty
//                folder; bundle.json cases: entries naming unclear or unsuitable files, invalid JSON, another
//                profile. Expected checklists: tests/synthetic/f1_checklist_matrix.json (written by hand).
//   sample/      CVI_sample_bundle_synthetic.zip: the landing page's downloadable sample, written here by the
//                page's own code (site/shared/sample.js, site/cvi/sample.js) for the tests to compare the download with.
// All values are synthetic. Facility files copy only the column names of CVI's reference files.
// The Full tier's content (master columns, facility layers, manifest, bundle.json) is generated by
// site/cvi/sample.js, shared with the landing page, so the sample download and the Full tier have the same files.
const fs = require('fs'), path = require('path'), zlib = require('zlib'), vm = require('vm');
const ROOT = path.resolve(__dirname, '..', '..');
require(path.join(ROOT, 'site', 'shared', 'zip.js'));
require(path.join(ROOT, 'site', 'shared', 'sample.js'));
require(path.join(ROOT, 'site', 'cvi', 'sample.js'));
const SAMPLE = globalThis.WSDA.samples.cvi;
const { rawRecords, csvText, fullMaster, MANIFEST: MANIFEST_TEXT, COVERAGE } = SAMPLE;
const facilityCsv = (kind, n) => Buffer.from(SAMPLE.facilityCsv(kind, n));
const MANIFEST = Buffer.from(MANIFEST_TEXT);
const bundleJson = o => Buffer.from(SAMPLE.bundleJson(o));
const OUT = path.join(ROOT, 'local-test-artifacts', 'f1');
const SYN = f => fs.readFileSync(path.join(__dirname, f));

// ---- minimal ZIP writer ----------------------------------------------------------------------------------------
const CRC = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
function crc32(b) { let c = 0xFFFFFFFF; for (let i = 0; i < b.length; i++) c = CRC[(c ^ b[i]) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; }
const DOS_TIME = 0x6000, DOS_DATE = ((2026 - 1980) << 9) | (9 << 5) | 15;   // 2026-09-15 12:00:00

/** entries: [{ name, data: Buffer, method?: 0|8, dir?: true, utf8?: bool, descriptor?: bool, flags?: number,
 *  forceMethod?: number, badCrc?: bool }]. Returns a Buffer. */
function makeZip(entries, opts) {
  opts = opts || {};
  const locals = [], centrals = []; let offset = 0;
  for (const e of entries) {
    const name = Buffer.from(e.dir && !e.name.endsWith('/') ? e.name + '/' : e.name, 'utf8');
    const raw = e.dir ? Buffer.alloc(0) : e.data;
    const method = e.dir ? 0 : (e.method === undefined ? 8 : e.method);
    const comp = method === 8 ? zlib.deflateRawSync(raw, { level: 9 }) : raw;
    const crc = e.badCrc ? (crc32(raw) ^ 0xFFFF) >>> 0 : crc32(raw);
    let flags = (e.utf8 ? 0x800 : 0) | (e.descriptor ? 0x8 : 0) | (e.flags || 0);
    const m = e.forceMethod === undefined ? method : e.forceMethod;
    const lh = Buffer.alloc(30);
    lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(flags, 6); lh.writeUInt16LE(m, 8);
    lh.writeUInt16LE(DOS_TIME, 10); lh.writeUInt16LE(DOS_DATE, 12);
    lh.writeUInt32LE(e.descriptor ? 0 : crc, 14); lh.writeUInt32LE(e.descriptor ? 0 : comp.length, 18); lh.writeUInt32LE(e.descriptor ? 0 : raw.length, 22);
    lh.writeUInt16LE(name.length, 26); lh.writeUInt16LE(0, 28);
    const parts = [lh, name, comp];
    if (e.descriptor) { const dd = Buffer.alloc(16); dd.writeUInt32LE(0x08074b50, 0); dd.writeUInt32LE(crc, 4); dd.writeUInt32LE(comp.length, 8); dd.writeUInt32LE(raw.length, 12); parts.push(dd); }
    const local = Buffer.concat(parts);
    const ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6); ch.writeUInt16LE(flags, 8); ch.writeUInt16LE(m, 10);   // made by MS-DOS: no Unix mode bits
    ch.writeUInt16LE(DOS_TIME, 12); ch.writeUInt16LE(DOS_DATE, 14); ch.writeUInt32LE(crc, 16); ch.writeUInt32LE(comp.length, 20); ch.writeUInt32LE(raw.length, 24);
    ch.writeUInt16LE(name.length, 28); ch.writeUInt32LE(e.dir ? 0x10 : 0, 38); ch.writeUInt32LE(offset, 42);   // MS-DOS folder attribute
    centrals.push(Buffer.concat([ch, name])); locals.push(local); offset += local.length;
  }
  const cen = Buffer.concat(centrals), comment = Buffer.from(opts.comment || '', 'utf8');
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); eocd.writeUInt16LE(entries.length, 8); eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(cen.length, 12); eocd.writeUInt32LE(offset, 16); eocd.writeUInt16LE(comment.length, 20);
  return Buffer.concat([...locals, cen, eocd, comment]);
}

function largeCsv(csv, times) {
  const text = csv.toString('utf8'), nl = text.indexOf('\n') + 1;
  return Buffer.concat([Buffer.from(text.slice(0, nl)), ...Array(times).fill(Buffer.from(text.slice(nl)))]);
}

// ---- outputs ---------------------------------------------------------------------------------------------------
const CHECKPOINT_BUNDLE_JSON = Buffer.from(JSON.stringify({ profile: 'cvi', label: 'Checkpoint – synthetic', prepared: '2026-09-15', coverage: { from: '2024-01-01', to: '2025-12-31' } }, null, 2) + '\n');

/** Archives that break the ZIP structure in ways a careless reader would accept. */
function hostileZips() {
  const csv = Buffer.from('Lat,Long\n1,2\n');
  const cen = b => b.readUInt32LE(b.length - 6);            // central directory offset (no archive comment)
  const out = {};
  let b = makeZip([{ name: 'a.csv', data: csv, method: 0 }]); b.write('b', 30); out.local_mismatch = b;     // local name b.csv
  b = makeZip([{ name: 'a.csv', data: csv, method: 0 }, { name: 'b.csv', data: csv, method: 0 }]);
  b.writeUInt32LE(0, cen(b) + 46 + 5 + 42); out.aliased = b;                                                // b.csv points at a.csv
  b = makeZip([{ name: 'a.csv', data: csv, method: 0 }]); b.writeUInt16LE(65535, cen(b) + 28); out.truncated_name = b;
  b = makeZip([{ name: 'a.csv', data: csv, method: 0 }]); b.writeUInt16LE(1, b.length - 18); b.writeUInt16LE(1, b.length - 16); out.split_disk = b;
  b = makeZip([{ name: 'x.csv', data: Buffer.from('x\n') }]); b.writeUInt32LE(512 * 1024 * 1024, cen(b) + 24); out.overstated_size = b;
  b = makeZip([{ name: 'a.csv', data: csv, method: 0 }]); b.writeUInt32LE(5000, cen(b) + 20); out.outside_data = b;   // size beyond the data
  out.duplicate_path = makeZip([{ name: 'master.csv', data: csv, method: 0 }, { name: 'master.csv', data: Buffer.from('Lat,Long\n3,4\n'), method: 0 }]);
  b = makeZip([{ name: 'e.csv', data: csv, method: 0 }]); b[30] = 0x82; b[cen(b) + 46] = 0x82; out.cp437_name = b;     // CP437 é, no UTF-8 flag
  b = makeZip([{ name: 'e.csv', data: csv, method: 0, utf8: true }]); b[30] = 0xFF; b[cen(b) + 46] = 0xFF; out.bad_utf8_name = b;
  return out;
}

function writeCheckpoint() {
  const dir = path.join(OUT, 'checkpoint');
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
  const small = SYN('cvi_master_small.csv'), wa = SYN('cvi_master_wa39.csv');
  const bundleJson = CHECKPOINT_BUNDLE_JSON;
  const zips = {
    'stored.zip': [{ name: 'cvi_master_small.csv', data: small, method: 0 }, { name: 'cvi_master_wa39.csv', data: wa, method: 0 }],
    'deflate.zip': [{ name: 'cvi_master_small.csv', data: small }, { name: 'cvi_master_wa39.csv', data: wa }, { name: 'bundle.json', data: bundleJson }],
    // Finder/ditto style: a top folder, data descriptors, UTF-8 names and __MACOSX metadata entries.
    'finder_style.zip': [
      { name: 'CVI bundle', dir: true },
      { name: 'CVI bundle/cvi_master_wa39.csv', data: wa, descriptor: true, utf8: true },
      { name: 'CVI bundle/Données – petit.csv', data: small, descriptor: true, utf8: true },
      { name: 'CVI bundle/.DS_Store', data: Buffer.from('synthetic'), descriptor: true },
      { name: '__MACOSX/CVI bundle/._cvi_master_wa39.csv', data: Buffer.from('synthetic'), descriptor: true }
    ],
    'nested_zip.zip': [{ name: 'cvi_master_small.csv', data: small }, { name: 'inner.zip', data: makeZip([{ name: 'x.csv', data: small }]) }],
    'empty.zip': [],
    'encrypted_entry.zip': [{ name: 'secret.csv', data: small, flags: 0x1 }, { name: 'cvi_master_small.csv', data: small }],
    'unsupported_method.zip': [{ name: 'bzip2.csv', data: small, method: 0, forceMethod: 12 }, { name: 'cvi_master_small.csv', data: small }],
    'bad_crc.zip': [{ name: 'cvi_master_small.csv', data: small, badCrc: true }],
    // ~58 MB master-shaped CSV (the WA fixture's rows repeated 400 times) to time extraction in the browser.
    'large_deflate.zip': [{ name: 'cvi_master_large.csv', data: largeCsv(wa, 400) }]
  };
  const written = {};
  for (const [name, entries] of Object.entries(zips)) { const b = makeZip(entries); fs.writeFileSync(path.join(dir, name), b); written[name] = b; }
  // Damaged archives: cut off at the end, and corrupted deflate data with a correct directory.
  fs.writeFileSync(path.join(dir, 'truncated.zip'), written['deflate.zip'].subarray(0, written['deflate.zip'].length - 40));
  const garbled = Buffer.from(written['deflate.zip']); for (let i = 40; i < 140; i++) garbled[i] ^= 0x5A;
  fs.writeFileSync(path.join(dir, 'garbled_data.zip'), garbled);
  fs.writeFileSync(path.join(dir, 'not_really.zip'), small);             // a CSV renamed .zip
  for (const [name, buf] of Object.entries(hostileZips())) fs.writeFileSync(path.join(dir, 'hostile_' + name + '.zip'), buf);
  // Folder tree for folder selection / drag-and-drop: subfolder, system clutter and a ZIP inside.
  const f = path.join(dir, 'folder', 'CVI data');
  fs.mkdirSync(path.join(f, 'facilities'), { recursive: true });
  fs.writeFileSync(path.join(f, 'cvi_master_wa39.csv'), wa);
  fs.writeFileSync(path.join(f, 'facilities', 'cvi_master_small.csv'), small);
  fs.writeFileSync(path.join(f, '.DS_Store'), 'synthetic');           // Finder may later remove or replace this one
  fs.writeFileSync(path.join(f, '._cvi_master_wa39.csv'), 'synthetic'); // AppleDouble metadata, as left by some copies
  fs.writeFileSync(path.join(f, 'Thumbs.db'), 'synthetic');
  fs.writeFileSync(path.join(f, 'extra.zip'), written['stored.zip']);
  fs.mkdirSync(path.join(dir, 'empty_folder'), { recursive: true });
  return dir;
}

// ---- tier bundles and negative cases ---------------------------------------------------------------------------
const REQUIRED = ['Species.Group', 'Reporting.Year', 'Reporting.Quarter', 'Movement', 'Total.Animals', 'Origin.State',
  'Dest.State', 'Origin.County', 'Origin.County.Lat', 'Origin.County.Long', 'Dest.County', 'Dest.County.Lat', 'Dest.County.Long'];

/** Master variants derived from the WA fixture: same rows, chosen columns (in the fixture's order). */
function masters() {
  const rows = rawRecords(SYN('cvi_master_wa39.csv').toString('utf8'));
  const head = rows[0];
  const pick = cols => rows.map(r => head.map((h, i) => cols.includes(h) ? r[i] : null).filter(v => v !== null));
  return {
    full: Buffer.from(fullMaster(SYN('cvi_master_wa39.csv').toString('utf8'))),
    partner: Buffer.from(csvText(pick(REQUIRED))),                       // exactly the 13 required columns
    public: Buffer.from(csvText(pick(REQUIRED.concat(['Species'])))),    // county-level columns + raw species
    missingTwo: Buffer.from(csvText(pick(REQUIRED.concat(['Species']).filter(c => c !== 'Dest.County.Lat' && c !== 'Dest.County.Long'))))
  };
}

// County label points, as the landing page reads them from site/geo/wa-counties.js for the sample download.
const LABELS = (() => { const sb = { window: {} }; vm.runInNewContext(fs.readFileSync(path.join(ROOT, 'site', 'geo', 'wa-counties.js'), 'utf8'), sb); return sb.window.CVIWA_GEO.labels; })();

/** Each tier: { files: { name: Buffer }, zipFolder?: top folder inside the ZIP }. The Full tier is generated from the
 * county labels (site/cvi/sample.js), like the sample download; masters() derives the others from the WA fixture. */
function tierContents() {
  const m = masters();
  return {
    full: (t => ({ zipFolder: t.zipFolder, files: Object.fromEntries(t.files.map(([n, d]) => [n, Buffer.from(d)])) }))(SAMPLE.fullTier(LABELS)),
    partner: { files: {
      'partner_county_totals.csv': m.partner,
      'wa_state_public_livestock_markets.csv': facilityCsv('markets', 5),
      'feedlots_2025.csv': facilityCsv('feedlots', 7),
      'bundle.json': bundleJson({ profile: 'cvi', label: 'Partner – county totals only', prepared: '2026-09-15', coverage: COVERAGE,
        files: { feedlots: 'feedlots_2025.csv' } })
    } },
    public: { files: { 'CVI_Consolidated_Master.csv': m.public } }
  };
}

/** A CSV with columns added at the end: values(k) gives row k's cells (k from 1). */
function withColumns(csv, cols, values) {
  return Buffer.from(csvText(rawRecords(csv.toString('utf8')).map((r, k) => r.concat(k === 0 ? cols : values(k)))));
}

const UNCLEAR_FAIRS = Buffer.from('﻿Fair Name,Type,Address,City\nSynthetic Fairground 1,County,Synthetic address,Synthetic Town 1\n');

function negativeContents() {
  const m = masters();
  return {
    wrong_file: {
      'CVI_Consolidated_Master.csv': m.missingTwo,
      'species_lookup.csv': Buffer.from('species_raw,species_group\nSynthetic goat,Goats\nSynthetic llama,Other\n'),
      'notes.txt': Buffer.from('Synthetic notes file.\n'),
      'summary.xlsx': makeZip([{ name: '[Content_Types].xml', data: Buffer.from('<Types/>') }, { name: 'xl/workbook.xml', data: Buffer.from('<workbook/>') }]),
      'layer.geojson': Buffer.from('{"type":"FeatureCollection","features":[]}\n'),
      'empty.csv': Buffer.alloc(0),
      'semicolon.csv': Buffer.from(REQUIRED.join(';') + '\n'),
      'utf16.csv': Buffer.concat([Buffer.from([0xFF, 0xFE]), Buffer.from(REQUIRED.join(',') + '\n', 'utf16le')]),
      'wide_header.csv': Buffer.from('c'.repeat(1100 * 1024) + '\n1\n')
    },
    // bundle.json entries that must not block other files, and a user pick that overrides one.
    bundle_edge: {
      'bad_master.csv': Buffer.from('x,y\n1,2\n'),
      'good_master.csv': m.public,
      'a.csv': facilityCsv('markets', 3),
      'wa_state_public_livestock_markets.csv': facilityCsv('markets', 5),
      'bundle.json': bundleJson({ profile: 'cvi', files: { master: 'bad_master.csv', markets: 'a.csv' } })
    },
    duplicate_master: { 'CVI_Consolidated_Master.csv': m.full, 'cvi_master_copy.csv': m.public },
    unclear_facility: {
      'CVI_Consolidated_Master.csv': m.public,
      'feedlots_2025.csv': facilityCsv('feedlots', 7),
      'packing_plants_2025.csv': facilityCsv('slaughterhouses', 6),
      'wa_state_fairs.csv': UNCLEAR_FAIRS
    },
    // bundle.js: the unclear files named in a real bundle.json; a bundle.json that is not valid JSON; one
    // that names another profile (its "files" entries must not be used for CVI).
    unclear_facility_bundle: {
      'CVI_Consolidated_Master.csv': m.public,
      'feedlots_2025.csv': facilityCsv('feedlots', 7),
      'packing_plants_2025.csv': facilityCsv('slaughterhouses', 6),
      'wa_state_fairs.csv': UNCLEAR_FAIRS,
      'bundle.json': bundleJson({ profile: 'cvi', files: { feedlots: 'feedlots_2025.csv', fairgrounds: 'wa_state_fairs.csv' } })
    },
    // bundle.json entries that do not fit must not stop a file being recognized by its columns.
    bundle_wrong_map: {
      'good.csv': m.public,
      'other.csv': facilityCsv('markets', 3),
      'bundle.json': bundleJson({ profile: 'cvi', files: { feedlots: 'good.csv', typo: 'other.csv' } })
    },
    bad_bundle: {
      'CVI_Consolidated_Master.csv': m.public,
      'bundle.json': Buffer.from('{ "profile": "cvi", "label": "Broken\n')
    },
    // A master with the extra columns a facility layer has (name, lat, long) is still the master, under any name,
    // including a facility layer's recommended name; an ordinary facility layer beside it is unaffected.
    master_extra_columns: {
      'movements_with_places.csv': withColumns(m.public, ['name', 'lat', 'long'], k => ['Synthetic place ' + k, '47.0000', '-122.0000']),
      'wa_state_public_livestock_markets.csv': facilityCsv('markets', 5)
    },
    master_named_like_facility: { 'wa_state_feedlots.csv': withColumns(m.public, ['lat', 'long'], () => ['47.0000', '-122.0000']) },
    other_profile_bundle: {
      'CVI_Consolidated_Master.csv': m.public,
      'feedlots_2025.csv': facilityCsv('feedlots', 7),
      // A dashboard this site does not have (it was "emergency" while that dashboard was in preparation).
      'bundle.json': bundleJson({ profile: 'reports', label: 'Reports – synthetic', files: { feedlots: 'feedlots_2025.csv' } })
    }
  };
}

function writeTree(dir, files) {
  fs.mkdirSync(dir, { recursive: true });
  for (const [name, data] of Object.entries(files)) fs.writeFileSync(path.join(dir, name), data);
}

function writeTiers() {
  const base = path.join(OUT, 'tiers');
  fs.rmSync(base, { recursive: true, force: true });
  for (const [tier, t] of Object.entries(tierContents())) {
    writeTree(path.join(base, tier), t.files);
    const pre = t.zipFolder ? t.zipFolder + '/' : '';
    const entries = (t.zipFolder ? [{ name: t.zipFolder, dir: true }] : [])
      .concat(Object.entries(t.files).map(([name, data]) => ({ name: pre + name, data, utf8: true })));
    fs.writeFileSync(path.join(base, tier + '.zip'), makeZip(entries));
  }
  return base;
}

function writeNegative() {
  const base = path.join(OUT, 'negative');
  fs.rmSync(base, { recursive: true, force: true });
  for (const [name, files] of Object.entries(negativeContents())) writeTree(path.join(base, name), files);
  const m = masters();                                    // same file name in two subfolders (ids, not paths)
  writeTree(path.join(base, 'same_name', 'a'), { 'CVI_Consolidated_Master.csv': m.full });
  writeTree(path.join(base, 'same_name', 'b'), { 'CVI_Consolidated_Master.csv': m.public });
  const full = fs.readFileSync(path.join(OUT, 'tiers', 'full.zip'));
  fs.writeFileSync(path.join(base, 'corrupt.zip'), full.subarray(0, Math.floor(full.length / 2)));   // cut in half
  fs.mkdirSync(path.join(base, 'empty_folder'), { recursive: true });
  return base;
}

/** The landing page's sample download, made by the page's own code (stored ZIP, deterministic). */
function sampleZip() { return Buffer.from(globalThis.WSDA.sample.zip(SAMPLE.entries(LABELS))); }

/** The all-in-one sample (AB): every dashboard's files in cvi/ and facilities/, made by the page's own code. */
function allInOne() { return globalThis.WSDA.sample.allDashboards(LABELS); }
function allInOneZip() { return Buffer.from(globalThis.WSDA.sample.zip(allInOne().entries)); }

function writeSample() {
  const base = path.join(OUT, 'sample');
  fs.rmSync(base, { recursive: true, force: true });
  fs.mkdirSync(base, { recursive: true });
  fs.writeFileSync(path.join(base, SAMPLE.fileName), sampleZip());
  fs.writeFileSync(path.join(base, allInOne().fileName), allInOneZip());
  return base;
}

function writeAll() { return [writeCheckpoint(), writeTiers(), writeNegative(), writeSample()]; }

if (require.main === module) {
  for (const dir of writeAll()) console.log('F1 fixtures written to ' + path.relative(ROOT, dir));
}
module.exports = { makeZip, crc32, rawRecords, largeCsv, writeCheckpoint, writeTiers, writeNegative, writeSample, writeAll, sampleZip, allInOne, allInOneZip, tierContents, LABELS, OUT, CHECKPOINT_BUNDLE_JSON };
